@import 'tailwindcss';
@import 'tw-animate-css';

@custom-variant dark (&:is(.dark *));

:root {
  /* Reorient brand palette: slate-navy base, warm white surface, steel-blue accent, amber signal */
  --background: oklch(0.972 0.004 240);
  --foreground: oklch(0.16 0.018 240);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.16 0.018 240);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.16 0.018 240);
  --primary: oklch(0.38 0.09 240);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.955 0.006 240);
  --secondary-foreground: oklch(0.28 0.022 240);
  --muted: oklch(0.955 0.006 240);
  --muted-foreground: oklch(0.5 0.018 240);
  --accent: oklch(0.52 0.13 220);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.577 0.22 27);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.9 0.008 240);
  --input: oklch(0.9 0.008 240);
  --ring: oklch(0.52 0.13 220);
  /* Signal colors */
  --signal-amber: oklch(0.72 0.16 65);
  --signal-green: oklch(0.58 0.14 155);
  --signal-red: oklch(0.57 0.2 27);
  --signal-slate: oklch(0.65 0.02 240);
  --chart-1: oklch(0.52 0.13 220);
  --chart-2: oklch(0.58 0.14 155);
  --chart-3: oklch(0.72 0.16 65);
  --chart-4: oklch(0.57 0.2 27);
  --chart-5: oklch(0.65 0.02 240);
  --radius: 0.5rem;
  --sidebar: oklch(0.22 0.025 240);
  --sidebar-foreground: oklch(0.88 0.01 240);
  --sidebar-primary: oklch(0.52 0.13 220);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.30 0.03 240);
  --sidebar-accent-foreground: oklch(0.88 0.01 240);
  --sidebar-border: oklch(0.30 0.03 240);
  --sidebar-ring: oklch(0.52 0.13 220);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.145 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.396 0.141 25.723);
  --destructive-foreground: oklch(0.637 0.237 25.331);
  --border: oklch(0.269 0 0);
  --input: oklch(0.269 0 0);
  --ring: oklch(0.439 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(0.269 0 0);
  --sidebar-ring: oklch(0.439 0 0);
}

@theme inline {
  --font-sans: 'Geist', 'Geist Fallback';
  --font-mono: 'Geist Mono', 'Geist Mono Fallback';
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-signal-amber: var(--signal-amber);
  --color-signal-green: var(--signal-green);
  --color-signal-red: var(--signal-red);
  --color-signal-slate: var(--signal-slate);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

export type UrgencyLevel = "critical" | "high" | "medium" | "low";
export type StatusType = "blocked" | "at-risk" | "on-track" | "resolved" | "done";
export type DependencyStatus = "waiting" | "in-review" | "unblocked" | "delivered";

export interface Decision {
  id: string;
  projectId: string;
  summary: string;
  rationale: string;
  decisionMaker: string;
  date: string; // ISO
  tags: string[];
}

export interface Blocker {
  id: string;
  projectId: string;
  title: string;
  owner: string;
  status: StatusType;
  openedDate: string; // ISO
  description: string;
  workstream: string;
}

export interface Dependency {
  id: string;
  projectId: string;
  blocker: string; // team/person blocking
  blocked: string; // team/person waiting
  nature: string; // what is needed
  status: DependencyStatus;
  dueDate: string;
  workstream: string;
}

export interface Project {
  id: string;
  name: string;
  workstream: string;
  urgency: UrgencyLevel;
  status: StatusType;
  lastTouchedDate: string; // ISO
  lastDecisionDate: string; // ISO
  activeBlockers: number;
  openDependencies: number;
  pm: string;
  description: string;
  freshnessDaysAgo: number;
}

