// ---------- Helper utilities ----------

export function getProjectById(id: string): Project | undefined {
  return projects.find((p) => p.id === id);
}

export function getDecisionsForProject(projectId: string): Decision[] {
  return decisions
    .filter((d) => d.projectId === projectId)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

export function getBlockersForProject(projectId: string): Blocker[] {
  return blockers.filter((b) => b.projectId === projectId);
}

export function getDependenciesForProject(projectId: string): Dependency[] {
  return dependencies.filter((d) => d.projectId === projectId);
}

export function formatRelativeDate(isoDate: string): string {
  const now = new Date("2025-07-22T12:00:00Z");
  const date = new Date(isoDate);
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  if (diffDays === 0) return "Today";
  if (diffDays === 1) return "Yesterday";
  if (diffDays < 7) return `${diffDays}d ago`;
  if (diffDays < 30) return `${Math.floor(diffDays / 7)}w ago`;
  return `${Math.floor(diffDays / 30)}mo ago`;
}

export function formatDate(isoDate: string): string {
  return new Date(isoDate).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

export function getBlockerAgeLabel(openedDate: string): string {
  const now = new Date("2025-07-22T12:00:00Z");
  const date = new Date(openedDate);
  const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60 * 24));
  return `${diffDays}d open`;
}

export function urgencyOrder(u: UrgencyLevel): number {
  return { critical: 0, high: 1, medium: 2, low: 3 }[u];
}

export function sortedProjects(by: "urgency" | "recency"): Project[] {
  return [...projects].sort((a, b) => {
    if (by === "urgency") {
      const uDiff = urgencyOrder(a.urgency) - urgencyOrder(b.urgency);
      if (uDiff !== 0) return uDiff;
      return new Date(b.lastTouchedDate).getTime() - new Date(a.lastTouchedDate).getTime();
    }
    return new Date(b.lastTouchedDate).getTime() - new Date(a.lastTouchedDate).getTime();
  });
}

