    badge: "bg-amber-50 border-amber-200",
    text: "text-signal-amber",
  },
  medium: {
    label: "Medium",
    dot: "bg-accent",
    badge: "bg-blue-50 border-blue-200",
    text: "text-accent",
  },
  low: {
    label: "Low",
    dot: "bg-signal-slate",
    badge: "bg-slate-50 border-slate-200",
    text: "text-signal-slate",
  },
};

function FreshnessBar({ days }: { days: number }) {
  const clamped = Math.min(days, 14);
  const pct = (clamped / 14) * 100;
  const color =
    days <= 2
      ? "bg-signal-green"
      : days <= 5
      ? "bg-signal-amber"
      : "bg-signal-red";
  const label =
    days <= 2 ? "Fresh" : days <= 5 ? "Getting stale" : "Needs update";

  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-center justify-between">
        <span className="text-[11px] text-muted-foreground font-medium tracking-wide uppercase">
          Freshness
        </span>
        <span
          className={`text-[11px] font-semibold ${
            days <= 2
              ? "text-signal-green"
              : days <= 5
              ? "text-signal-amber"
              : "text-signal-red"
          }`}
        >
          {label}
        </span>
      </div>
      <div className="h-1 w-full bg-border rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full transition-all ${color}`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span className="text-[10px] text-muted-foreground">
        Last updated {days === 0 ? "today" : `${days}d ago`}
      </span>
    </div>
  );
}

