interface DecisionLogProps {
  project: Project;
  onBack: () => void;
  onGoToSnapshot: () => void;
  onGoToDependencies: () => void;
  extraDecisions: Decision[];
  onAddDecision: (d: Omit<Decision, "id" | "projectId">) => void;
}

const ALL_TAGS = ["architecture", "ux", "scope", "auth", "design", "mobile", "api-design", "data", "payments", "security", "experiment", "deadline", "partners", "dx", "rate-limiting", "copy", "infrastructure", "activation"];

function AddDecisionInline({
  projectId,
  onSave,
  onCancel,
}: {
  projectId: string;
  onSave: (d: Omit<Decision, "id" | "projectId">) => void;
  onCancel: () => void;
}) {
  const [summary, setSummary] = useState("");
  const [rationale, setRationale] = useState("");
  const [decisionMaker, setDecisionMaker] = useState("Jordan Kim");
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [submitted, setSubmitted] = useState(false);

  const canSave = summary.trim().length > 0 && rationale.trim().length > 0;

  function handleSave() {
    if (!canSave) return;
    setSubmitted(true);
    setTimeout(() => {
      onSave({
        summary: summary.trim(),
        rationale: rationale.trim(),
        decisionMaker,
        date: new Date().toISOString(),
        tags: selectedTags,
      });
    }, 900);
  }

  function toggleTag(tag: string) {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  }

  if (submitted) {
    return (
      <div className="border border-signal-green/40 bg-green-50 rounded-lg p-5 flex items-center gap-3">
        <CheckCircle2 className="w-5 h-5 text-signal-green shrink-0" />
        <div>
          <p className="text-sm font-semibold text-foreground">Decision logged</p>
          <p className="text-xs text-muted-foreground">Added to the top of the log.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="border border-accent/30 bg-card rounded-lg p-5 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Plus className="w-4 h-4 text-accent" />
          <span className="text-xs font-semibold text-foreground uppercase tracking-wide">
            New Decision
          </span>
        </div>
        <button onClick={onCancel} className="text-muted-foreground hover:text-foreground transition-colors">
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="flex flex-col gap-4">
        <div>
          <label className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide block mb-1.5">
            Decision Summary *
          </label>
          <input
            type="text"
            placeholder="What was decided?"
            value={summary}
            onChange={(e) => setSummary(e.target.value)}
            className="w-full text-sm border border-border rounded-md px-3 py-2 bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
          />
        </div>

        <div>
          <label className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide block mb-1.5">
            Rationale *
          </label>
          <textarea
            placeholder="Why was this decision made? What tradeoffs were considered?"
            value={rationale}
            onChange={(e) => setRationale(e.target.value)}
            rows={3}
            className="w-full text-sm border border-border rounded-md px-3 py-2 bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring resize-none leading-relaxed"
          />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex-1">
            <label className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide block mb-1.5">
              Decision Maker
            </label>
            <input
              type="text"
              value={decisionMaker}
              onChange={(e) => setDecisionMaker(e.target.value)}
              className="w-full text-sm border border-border rounded-md px-3 py-2 bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
            />
          </div>
          <div className="flex-1">
            <label className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide block mb-1.5">
              Date
            </label>
            <div className="text-sm border border-border rounded-md px-3 py-2 bg-secondary text-muted-foreground">
              Today
            </div>
          </div>
        </div>

        <div>
          <label className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide block mb-1.5">
            Tags
          </label>
          <div className="flex flex-wrap gap-1.5">
            {ALL_TAGS.slice(0, 10).map((tag) => (
              <button
                key={tag}
                onClick={() => toggleTag(tag)}
                className={`text-[11px] px-2 py-0.5 rounded-full border transition-colors ${
                  selectedTags.includes(tag)
                    ? "bg-accent text-accent-foreground border-accent"
                    : "bg-secondary text-muted-foreground border-border hover:border-accent/40"
                }`}
              >
                {tag}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center justify-end gap-2 pt-2">
          <button
            onClick={onCancel}
            className="text-xs text-muted-foreground hover:text-foreground px-3 py-1.5 transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleSave}
            disabled={!canSave}
            className="flex items-center gap-1.5 text-xs font-semibold bg-accent text-accent-foreground px-4 py-1.5 rounded-md hover:bg-accent/90 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <CheckCircle2 className="w-3.5 h-3.5" />
            Save Decision
          </button>
        </div>
      </div>
    </div>
  );
}

