  const [showAddForm, setShowAddForm] = useState(false);

  const baseDecisions = getDecisionsForProject(project.id);
  const allDecisions = [...extraDecisions, ...baseDecisions];

  const filtered = allDecisions.filter((d) => {
    const matchSearch =
      !search ||
      d.summary.toLowerCase().includes(search.toLowerCase()) ||
      d.rationale.toLowerCase().includes(search.toLowerCase()) ||
      d.decisionMaker.toLowerCase().includes(search.toLowerCase());
    const matchTag = !filterTag || d.tags.includes(filterTag);
    return matchSearch && matchTag;
  });

  const allTagsInLog = Array.from(new Set(allDecisions.flatMap((d) => d.tags)));

  function handleAddDecision(d: Omit<Decision, "id" | "projectId">) {
    onAddDecision(d);
    setShowAddForm(false);
