            <span>
              <span className="font-semibold text-foreground">{filtered.length}</span>{" "}
              {filtered.length === 1 ? "decision" : "decisions"}
              {filterTag && ` tagged "${filterTag}"`}
              {search && ` matching "${search}"`}
            </span>
            <span className="ml-auto text-[11px]">Append-only — sorted newest first</span>
          </div>

          {/* Decision entries */}
          <div className="flex flex-col gap-3">
            {filtered.map((d) => (
              <DecisionEntry key={d.id} decision={d} />
            ))}
            {filtered.length === 0 && (
              <div className="text-center py-12 text-sm text-muted-foreground">
                No decisions match your filters.
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  ArrowLeft,
  ArrowRight,
  BookOpen,
  ChevronRight,
  Filter,
  GitBranch,
  Layers,
  CheckCircle2,
  Clock,
  AlertTriangle,
  RotateCcw,
} from "lucide-react";
import {
  Project,
  Dependency,
  DependencyStatus,
  getDependenciesForProject,
  formatDate,
} from "@/lib/data";

interface DependencyBoardProps {
  project: Project;
  onBack: () => void;
  onGoToSnapshot: () => void;
  onGoToDecisions: () => void;
  onUpdateDepStatus: (id: string, status: DependencyStatus) => void;
  extraDeps?: Partial<Record<string, DependencyStatus>>;
}

const STATUS_CONFIG: Record<
  DependencyStatus,
  {
    label: string;
    color: string;
    bg: string;
    border: string;
    icon: React.ReactNode;
    rowBg: string;
  }
> = {
  waiting: {
    label: "Waiting",
    color: "text-signal-amber",
    bg: "bg-amber-50",
    border: "border-amber-200",
    icon: <Clock className="w-3.5 h-3.5" />,
    rowBg: "bg-amber-50/30",
  },
  "in-review": {
    label: "In Review",
    color: "text-accent",
    bg: "bg-blue-50",
    border: "border-blue-200",
    icon: <RotateCcw className="w-3.5 h-3.5" />,
    rowBg: "bg-blue-50/20",
  },
  unblocked: {
    label: "Unblocked",
    color: "text-signal-green",
    bg: "bg-green-50",
    border: "border-green-200",
    icon: <CheckCircle2 className="w-3.5 h-3.5" />,
    rowBg: "bg-green-50/20",
  },
  delivered: {
    label: "Delivered",
    color: "text-muted-foreground",
    bg: "bg-secondary",
    border: "border-border",
    icon: <CheckCircle2 className="w-3.5 h-3.5" />,
    rowBg: "bg-background",
  },
};

const STATUS_FLOW: DependencyStatus[] = ["waiting", "in-review", "unblocked", "delivered"];

function StatusChip({
  status,
  onClick,
}: {
  status: DependencyStatus;
  onClick?: () => void;
}) {
  const cfg = STATUS_CONFIG[status];
  return (
    <button
      onClick={onClick}
      className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold border transition-all hover:opacity-80 ${cfg.bg} ${cfg.border} ${cfg.color}`}
    >
      {cfg.icon}
      {cfg.label}
    </button>
  );
}

function DepRow({
  dep,
  overrideStatus,
  onAdvance,
}: {
  dep: Dependency;
  overrideStatus?: DependencyStatus;
  onAdvance: (id: string, next: DependencyStatus) => void;
}) {
  const status = overrideStatus ?? dep.status;
  const cfg = STATUS_CONFIG[status];
  const currentIdx = STATUS_FLOW.indexOf(status);
  const nextStatus = currentIdx < STATUS_FLOW.length - 1 ? STATUS_FLOW[currentIdx + 1] : null;

  const today = new Date("2025-07-22");
  const dueDate = new Date(dep.dueDate);
  const daysUntil = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
  const isOverdue = daysUntil < 0;
  const isDueSoon = daysUntil >= 0 && daysUntil <= 3;

  return (
    <tr className={`border-b border-border/60 hover:bg-secondary/40 transition-colors ${cfg.rowBg}`}>
      {/* Blocked party */}
      <td className="px-4 py-3">
        <span className="text-xs font-semibold text-foreground">{dep.blocked}</span>
      </td>

      {/* Arrow */}
      <td className="px-2 py-3 text-center">
        <ArrowRight className="w-3.5 h-3.5 text-muted-foreground mx-auto" />
      </td>

      {/* Blocker */}
      <td className="px-4 py-3">
        <span className="text-xs font-semibold text-foreground">{dep.blocker}</span>
      </td>

      {/* Nature */}
      <td className="px-4 py-3 max-w-xs">
        <p className="text-xs text-foreground">{dep.nature}</p>
        <span className="text-[10px] text-muted-foreground bg-secondary px-1.5 py-0.5 rounded-full mt-1 inline-block">
          {dep.workstream}
        </span>
      </td>

      {/* Due date */}
      <td className="px-4 py-3">
        <div
          className={`text-xs font-medium ${
            isOverdue
              ? "text-signal-red"
              : isDueSoon
              ? "text-signal-amber"
              : "text-muted-foreground"
          }`}
        >
          {formatDate(dep.dueDate)}
          {isOverdue && (
            <span className="ml-1 text-[10px] font-semibold">OVERDUE</span>
          )}
          {isDueSoon && !isOverdue && (
            <span className="ml-1 text-[10px]">({daysUntil}d)</span>
          )}
        </div>
      </td>

      {/* Status + advance */}
      <td className="px-4 py-3">
        <div className="flex items-center gap-2">
          <StatusChip
            status={status}
            onClick={
              nextStatus ? () => onAdvance(dep.id, nextStatus) : undefined
            }
          />
          {nextStatus && (
            <span className="text-[10px] text-muted-foreground hidden sm:block">
              → {STATUS_CONFIG[nextStatus].label}
            </span>
          )}
        </div>
      </td>
    </tr>
  );
}

// Visual matrix: who is waiting on whom
function MatrixView({
  deps,
  overrides,
}: {
  deps: Dependency[];
  overrides: Partial<Record<string, DependencyStatus>>;
}) {
  const parties = Array.from(
    new Set([...deps.map((d) => d.blocker), ...deps.map((d) => d.blocked)])
  );

  // For each (row=blocked, col=blocker) pair, find dependency
  const getCell = (blocked: string, blocker: string) => {
    if (blocked === blocker) return null;
    const dep = deps.find((d) => d.blocked === blocked && d.blocker === blocker);
    if (!dep) return null;
    return { dep, status: (overrides[dep.id] ?? dep.status) as DependencyStatus };
  };

  const colorMap: Record<DependencyStatus, string> = {
    waiting: "bg-signal-amber/20 border-signal-amber/40 text-signal-amber",
    "in-review": "bg-accent/15 border-accent/30 text-accent",
    unblocked: "bg-signal-green/15 border-signal-green/30 text-signal-green",
    delivered: "bg-secondary border-border text-muted-foreground",
  };

  return (
    <div className="overflow-x-auto">
      <table className="text-[10px] border-collapse w-full">
        <thead>
          <tr>
            <th className="text-left px-3 py-2 text-muted-foreground font-medium bg-secondary/60 border border-border rounded-tl-md">
              Waiting ↓ / Blocking →
            </th>
            {parties.map((p) => (
              <th
                key={p}
                className="px-3 py-2 text-muted-foreground font-medium bg-secondary/60 border border-border text-center whitespace-nowrap"
              >
                {p}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {parties.map((blocked) => (
            <tr key={blocked}>
              <td className="px-3 py-2 text-xs font-semibold text-foreground bg-secondary/40 border border-border whitespace-nowrap">
                {blocked}
              </td>
              {parties.map((blocker) => {
                if (blocked === blocker) {
                  return (
                    <td
                      key={blocker}
                      className="px-3 py-2 bg-secondary/60 border border-border text-center text-muted-foreground"
                    >
                      —
                    </td>
                  );
                }
                const cell = getCell(blocked, blocker);
                if (!cell) {
                  return (
                    <td
                      key={blocker}
                      className="px-3 py-2 bg-background border border-border text-center text-muted-foreground/30"
                    >
                      ·
                    </td>
                  );
                }
                const cfg = colorMap[cell.status];
                return (
                  <td key={blocker} className="px-3 py-2 border border-border text-center">
                    <span
                      className={`inline-block px-1.5 py-0.5 rounded border text-[10px] font-semibold ${cfg}`}
                    >
                      {STATUS_CONFIG[cell.status].label}
                    </span>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function DependencyBoard({
  project,
