              </div>
              <MatrixView deps={deps} overrides={localOverrides} />
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  AlertCircle,
  AlertTriangle,
  ArrowLeft,
  ArrowRight,
  CheckCircle2,
  Clock,
  Layers,
  RefreshCw,
  TrendingUp,
  Zap,
} from "lucide-react";
import {
  projects,
  blockers,
  decisions,
  formatRelativeDate,
  getBlockerAgeLabel,
} from "@/lib/data";

interface UpdatePulseProps {
  onBack: () => void;
  onSelectProject: (id: string) => void;
}

// Stale: no decision in >7 days
const staleProjects = projects
  .filter((p) => p.freshnessDaysAgo >= 5)
  .sort((a, b) => b.freshnessDaysAgo - a.freshnessDaysAgo);

// Overdue-for-followup: decision > 14 days old
const overdueDecisions = decisions
  .filter((d) => {
    const daysSince =
      (new Date("2025-07-22").getTime() - new Date(d.date).getTime()) /
      (1000 * 60 * 60 * 24);
    return daysSince > 14;
  })
  .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

// Long-open blockers: opened more than 5 days ago and still active
const longOpenBlockers = blockers
  .filter((b) => {
    const daysOpen =
      (new Date("2025-07-22").getTime() - new Date(b.openedDate).getTime()) /
      (1000 * 60 * 60 * 24);
    return daysOpen >= 5 && b.status !== "resolved";
  })
  .sort(
    (a, b) =>
      new Date(a.openedDate).getTime() - new Date(b.openedDate).getTime()
  );

function FreshnessGauge({ days }: { days: number }) {
  const max = 14;
  const pct = Math.min((days / max) * 100, 100);
  const color =
    days <= 2
      ? "bg-signal-green"
      : days <= 5
      ? "bg-signal-amber"
      : "bg-signal-red";

  return (
    <div className="flex items-center gap-2">
      <div className="flex-1 h-1.5 bg-border rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full ${color}`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span
        className={`text-[11px] font-semibold shrink-0 ${
          days <= 2
            ? "text-signal-green"
            : days <= 5
            ? "text-signal-amber"
            : "text-signal-red"
        }`}
      >
        {days}d
      </span>
    </div>
  );
}

