function DecisionFollowUpCard({
  decision,
}: {
  decision: (typeof decisions)[0];
}) {
  const project = projects.find((p) => p.id === decision.projectId);
  const daysSince = Math.floor(
    (new Date("2025-07-22").getTime() - new Date(decision.date).getTime()) /
      (1000 * 60 * 60 * 24)
  );

  return (
    <div className="bg-card border border-amber-200 rounded-lg p-4 flex items-start gap-4">
      <div className="mt-0.5 text-signal-amber shrink-0">
        <Clock className="w-4 h-4" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-foreground mb-0.5 text-pretty">
          {decision.summary}
        </p>
        {project && (
          <p className="text-xs text-muted-foreground mb-1">{project.name}</p>
        )}
        <div className="flex items-center gap-3">
          <span className="text-xs text-muted-foreground">
            Decided{" "}
            <span className="font-medium text-foreground">
              {formatRelativeDate(decision.date)}
            </span>
          </span>
          <span className="text-xs text-signal-amber font-medium">
            {daysSince}d — follow up due
          </span>
        </div>
      </div>
    </div>
  );
}

