"use client";

import { useState } from "react";
import { Zap } from "lucide-react";
import CommandCenter from "@/components/command-center";
import ProjectSnapshot from "@/components/project-snapshot";
import DecisionLog from "@/components/decision-log";
import DependencyBoard from "@/components/dependency-board";
import UpdatePulse from "@/components/update-pulse";
import { Decision, DependencyStatus, getProjectById } from "@/lib/data";

type Screen =
  | { id: "command-center" }
  | { id: "snapshot"; projectId: string }
  | { id: "decisions"; projectId: string }
  | { id: "dependencies"; projectId: string }
  | { id: "pulse" };

export default function ReorientApp() {
  const [screen, setScreen] = useState<Screen>({ id: "command-center" });

  // Shared mutable state: extra decisions and dep status overrides (keyed by depId)
  const [extraDecisions, setExtraDecisions] = useState<
    Record<string, Decision[]>
  >({});
  const [depOverrides, setDepOverrides] = useState<
    Record<string, DependencyStatus>
  >({});

  function goToProject(projectId: string) {
    setScreen({ id: "snapshot", projectId });
  }

  function goToDecisions(projectId: string) {
    setScreen({ id: "decisions", projectId });
  }

  function goToDependencies(projectId: string) {
    setScreen({ id: "dependencies", projectId });
  }

  function goToSnapshot(projectId: string) {
    setScreen({ id: "snapshot", projectId });
  }

  function goToCommandCenter() {
    setScreen({ id: "command-center" });
  }

  function goToPulse() {
    setScreen({ id: "pulse" });
  }

  function handleAddDecision(
    projectId: string,
    d: Omit<Decision, "id" | "projectId">
  ) {
    const newDecision: Decision = {
      id: `new-${Date.now()}`,
      projectId,
      ...d,
    };
    setExtraDecisions((prev) => ({
      ...prev,
      [projectId]: [newDecision, ...(prev[projectId] ?? [])],
    }));
  }

  function handleUpdateDepStatus(depId: string, status: DependencyStatus) {
    setDepOverrides((prev) => ({ ...prev, [depId]: status }));
  }

  // Bottom nav shown on all screens
  const navItems: Array<{
    label: string;
    screenId: string;
    icon: React.ReactNode;
    onClick: () => void;
  }> = [
    {
      label: "Command Center",
      screenId: "command-center",
      icon: <span className="text-base leading-none">⊞</span>,
      onClick: goToCommandCenter,
    },
    {
      label: "Update Pulse",
      screenId: "pulse",
      icon: <Zap className="w-4 h-4" />,
      onClick: goToPulse,
    },
  ];

  const currentScreenId = screen.id;

  return (
    <div className="relative min-h-screen bg-background">
      {/* Main content */}
      {screen.id === "command-center" && (
        <CommandCenter onSelectProject={goToProject} />
      )}

      {screen.id === "snapshot" && (() => {
        const project = getProjectById(screen.projectId);
        if (!project) return null;
        return (
          <ProjectSnapshot
            project={project}
            onBack={goToCommandCenter}
            onGoToDecisions={() => goToDecisions(screen.projectId)}
            onGoToDependencies={() => goToDependencies(screen.projectId)}
            onAddDecision={() => goToDecisions(screen.projectId)}
          />
        );
      })()}

      {screen.id === "decisions" && (() => {
        const project = getProjectById(screen.projectId);
        if (!project) return null;
        return (
          <DecisionLog
            project={project}
            onBack={goToCommandCenter}
            onGoToSnapshot={() => goToSnapshot(screen.projectId)}
            onGoToDependencies={() => goToDependencies(screen.projectId)}
            extraDecisions={extraDecisions[screen.projectId] ?? []}
            onAddDecision={(d) => handleAddDecision(screen.projectId, d)}
          />
        );
      })()}

      {screen.id === "dependencies" && (() => {
        const project = getProjectById(screen.projectId);
        if (!project) return null;
        return (
          <DependencyBoard
            project={project}
            onBack={goToCommandCenter}
            onGoToSnapshot={() => goToSnapshot(screen.projectId)}
            onGoToDecisions={() => goToDecisions(screen.projectId)}
            onUpdateDepStatus={handleUpdateDepStatus}
            extraDeps={depOverrides}
          />
        );
      })()}

      {screen.id === "pulse" && (
        <UpdatePulse
          onBack={goToCommandCenter}
          onSelectProject={goToProject}
        />
      )}

      {/* Global bottom nav */}
      <nav className="fixed bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-1 bg-sidebar border border-sidebar-border rounded-full px-2 py-1.5 shadow-lg z-50">
        <button
          onClick={goToCommandCenter}
          className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full transition-all ${
            currentScreenId === "command-center"
              ? "bg-sidebar-primary text-sidebar-primary-foreground font-semibold"
              : "text-sidebar-foreground hover:bg-sidebar-accent"
          }`}
        >
          <span className="text-sm leading-none font-mono">⊞</span>
          <span className="hidden sm:inline">Command Center</span>
        </button>

        {/* Project sub-nav — only shown when inside a project */}
        {(screen.id === "snapshot" ||
          screen.id === "decisions" ||
          screen.id === "dependencies") && (
          <>
            <div className="w-px h-5 bg-sidebar-border mx-1" />
            <button
              onClick={() =>
                screen.id !== "command-center" &&
                screen.id !== "pulse" &&
                goToSnapshot(
                  (screen as { projectId: string }).projectId
                )
              }
              className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full transition-all ${
                currentScreenId === "snapshot"
                  ? "bg-sidebar-primary text-sidebar-primary-foreground font-semibold"
                  : "text-sidebar-foreground hover:bg-sidebar-accent"
              }`}
            >
              Snapshot
            </button>
            <button
              onClick={() =>
                screen.id !== "command-center" &&
                screen.id !== "pulse" &&
                goToDecisions(
                  (screen as { projectId: string }).projectId
                )
              }
              className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full transition-all ${
                currentScreenId === "decisions"
                  ? "bg-sidebar-primary text-sidebar-primary-foreground font-semibold"
                  : "text-sidebar-foreground hover:bg-sidebar-accent"
              }`}
            >
              Decisions
            </button>
            <button
              onClick={() =>
                screen.id !== "command-center" &&
                screen.id !== "pulse" &&
                goToDependencies(
                  (screen as { projectId: string }).projectId
                )
              }
              className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full transition-all ${
                currentScreenId === "dependencies"
                  ? "bg-sidebar-primary text-sidebar-primary-foreground font-semibold"
                  : "text-sidebar-foreground hover:bg-sidebar-accent"
              }`}
            >
              Dependencies
            </button>
          </>
        )}

        <div className="w-px h-5 bg-sidebar-border mx-1" />

        <button
          onClick={goToPulse}
          className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full transition-all ${
            currentScreenId === "pulse"
              ? "bg-sidebar-primary text-sidebar-primary-foreground font-semibold"
              : "text-sidebar-foreground hover:bg-sidebar-accent"
          }`}
        >
          <Zap className="w-3.5 h-3.5" />
          <span className="hidden sm:inline">Pulse</span>
        </button>
      </nav>
    </div>
  );
}

